begin;
create extension if not exists pgcrypto;

create type public.fas_record_status as enum ('draft','user_approved','retired');
create type public.fas_basis as enum ('user','import','suggestion');
create type public.fas_member_role as enum ('owner','editor','viewer');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workspaces (id uuid primary key default gen_random_uuid(), name text not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid references public.workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role public.fas_member_role not null default 'viewer', created_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.projects (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, status text not null default 'active' check(status in ('active','archived','deleted')), created_by uuid not null references auth.users(id), deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.agent_definitions (key text primary key, version integer not null default 1, name text not null, definition jsonb not null default '{}'::jsonb, active boolean not null default true, created_at timestamptz not null default now());
create table public.interview_sessions (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, agent_key text not null references public.agent_definitions(key), state jsonb not null default '{}'::jsonb, checkpoint jsonb not null default '{}'::jsonb, status text not null default 'active' check(status in ('active','paused','complete')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.answers (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.interview_sessions(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, agent_key text not null, field_path text not null, value jsonb not null, basis text not null default 'user' check (basis in ('user', 'import', 'suggestion')), permission_status text not null default 'not_required' check(permission_status in ('not_required','pending','private','public')), supersedes_id uuid references public.answers(id), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.facts (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, field_path text not null, value jsonb not null, status text not null default 'draft' check (status in ('draft', 'user_approved', 'retired')), basis text not null default 'user' check (basis in ('user', 'import', 'suggestion')), version integer not null default 1, source_answer_id uuid references public.answers(id), approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz not null default now(), unique(project_id,field_path,version));
create table public.evidence_sources (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, source_type text not null check(source_type in ('answer','paste','quote','file','url')), label text not null, locator text, exact_text text, permission_status text not null default 'pending' check(permission_status in ('pending','private','public','not_required')), metadata jsonb not null default '{}'::jsonb, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.approvals (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, entity_type text not null, entity_id uuid not null, version integer not null, decision text not null check(decision in ('approved','rejected','retired')), decided_by uuid not null references auth.users(id), note text, created_at timestamptz not null default now());
create table public.gaps (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, agent_key text not null, field_path text not null, prompt text not null, status text not null default 'open' check(status in ('open','resolved','waived')), created_at timestamptz not null default now());
create table public.conflicts (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, field_path text not null, candidate_values jsonb not null, status text not null default 'open' check(status in ('open','resolved')), resolution jsonb, resolved_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.artifacts (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, agent_key text not null, artifact_type text not null, title text not null, current_version integer not null default 1, status text not null default 'draft' check (status in ('draft', 'user_approved', 'retired')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.artifact_versions (id uuid primary key default gen_random_uuid(), artifact_id uuid not null references public.artifacts(id) on delete cascade, version integer not null, content jsonb not null, input_snapshot jsonb not null default '{}'::jsonb, status text not null default 'draft' check (status in ('draft', 'user_approved', 'retired')), checksum text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(artifact_id,version));
create table public.exports (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, artifact_version_id uuid not null references public.artifact_versions(id), format text not null check(format in ('pdf','docx')), status text not null default 'queued' check(status in ('queued','complete','failed')), object_key text, checksum text, error_code text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.artifact_dependencies (artifact_version_id uuid references public.artifact_versions(id) on delete cascade, fact_id uuid references public.facts(id), fact_version integer not null, stale boolean not null default false, primary key(artifact_version_id,fact_id));
create table public.event_log (id bigint generated always as identity primary key, project_id uuid references public.projects(id) on delete cascade, user_id uuid references auth.users(id), event_type text not null, agent_key text, metadata jsonb not null default '{}'::jsonb check (octet_length(metadata::text) <= 4096), created_at timestamptz not null default now());
create table public.launch_tasks (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, phase text not null, title text not null, owner_name text, due_date date, dependency_ids uuid[] not null default '{}', status text not null default 'not_started', final_link text, notes text, created_at timestamptz not null default now());
create table public.sales_records (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, lead_name text not null, source text, stage text not null, next_action text, next_date date, offer text, result text, revenue numeric(12,2), created_at timestamptz not null default now());

create or replace function public.is_workspace_member(target_workspace uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from workspace_members where workspace_id=target_workspace and user_id=auth.uid()) $$;
create or replace function public.can_edit_workspace(target_workspace uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from workspace_members where workspace_id=target_workspace and user_id=auth.uid() and role in ('owner','editor')) $$;
create or replace function public.can_access_project(target_project uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from projects p where p.id=target_project and is_workspace_member(p.workspace_id)) $$;
create or replace function public.can_edit_project(target_project uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from projects p where p.id=target_project and can_edit_workspace(p.workspace_id)) $$;

alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.projects enable row level security; alter table public.agent_definitions enable row level security; alter table public.interview_sessions enable row level security; alter table public.answers enable row level security; alter table public.facts enable row level security; alter table public.evidence_sources enable row level security; alter table public.approvals enable row level security; alter table public.gaps enable row level security; alter table public.conflicts enable row level security; alter table public.artifacts enable row level security; alter table public.artifact_versions enable row level security; alter table public.exports enable row level security; alter table public.artifact_dependencies enable row level security; alter table public.event_log enable row level security; alter table public.launch_tasks enable row level security; alter table public.sales_records enable row level security;

create policy profiles_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy workspaces_members on public.workspaces for select using(public.is_workspace_member(id));
create policy workspace_members_visible on public.workspace_members for select using(public.is_workspace_member(workspace_id));
create policy projects_members on public.projects for select using(public.is_workspace_member(workspace_id));
create policy projects_editors on public.projects for all using(public.can_edit_workspace(workspace_id)) with check(public.can_edit_workspace(workspace_id));
create policy agent_definitions_read on public.agent_definitions for select to authenticated using(active=true);
create policy sessions_read on public.interview_sessions for select using(public.can_access_project(project_id));
create policy interview_sessions_edit on public.interview_sessions for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy answers_read on public.answers for select using(public.can_access_project(project_id));
create policy answers_edit on public.answers for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy facts_read on public.facts for select using(public.can_access_project(project_id));
create policy facts_edit on public.facts for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy evidence_read on public.evidence_sources for select using(public.can_access_project(project_id));
create policy evidence_sources_edit on public.evidence_sources for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy approvals_read on public.approvals for select using(public.can_access_project(project_id));
create policy approvals_edit on public.approvals for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy gaps_read on public.gaps for select using(public.can_access_project(project_id));
create policy gaps_edit on public.gaps for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy conflicts_read on public.conflicts for select using(public.can_access_project(project_id));
create policy conflicts_edit on public.conflicts for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy artifacts_read on public.artifacts for select using(public.can_access_project(project_id));
create policy artifacts_edit on public.artifacts for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy artifact_versions_read on public.artifact_versions for select using(public.can_access_project((select project_id from public.artifacts where id=artifact_id)));
create policy artifact_versions_edit on public.artifact_versions for all using(public.can_edit_project((select project_id from public.artifacts where id=artifact_id))) with check(public.can_edit_project((select project_id from public.artifacts where id=artifact_id)));
create policy exports_read on public.exports for select using(public.can_access_project(project_id));
create policy exports_edit on public.exports for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy dependencies_members on public.artifact_dependencies for select using(public.can_access_project((select a.project_id from public.artifact_versions v join public.artifacts a on a.id=v.artifact_id where v.id=artifact_version_id)));
create policy events_members on public.event_log for insert with check(public.can_access_project(project_id));
create policy launch_read on public.launch_tasks for select using(public.can_access_project(project_id));
create policy launch_edit on public.launch_tasks for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));
create policy sales_read on public.sales_records for select using(public.can_access_project(project_id));
create policy sales_edit on public.sales_records for all using(public.can_edit_project(project_id)) with check(public.can_edit_project(project_id));

create or replace function public.prevent_approved_history_mutation() returns trigger language plpgsql as $$ begin if old.status='user_approved' then raise exception 'approved history is immutable'; end if; return new; end $$;
create trigger prevent_approved_fact_mutation before update or delete on public.facts for each row execute function public.prevent_approved_history_mutation();
create trigger prevent_approved_artifact_version_mutation before update or delete on public.artifact_versions for each row execute function public.prevent_approved_history_mutation();
commit;

